-- Optional production persistence. The challenge demo runs locally without credentials.
create extension if not exists pgcrypto;
create type public.participant_role as enum ('shopper','friend');
create table public.boards (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users, occasion_id text not null check (occasion_id in ('wedding','birthday','festival')), brief jsonb not null default '{}', weights jsonb not null default '{"you":50,"friends":30,"fit":20}', approved_at timestamptz, created_at timestamptz not null default now());
create table public.participants (id uuid primary key default gen_random_uuid(), board_id uuid not null references public.boards on delete cascade, user_id uuid references auth.users, nickname text not null check (length(nickname) between 1 and 40), role public.participant_role not null, expires_at timestamptz, unique(board_id,user_id));
create table public.votes (id uuid primary key default gen_random_uuid(), board_id uuid not null references public.boards on delete cascade, module_id text not null, candidate_id text not null, participant_id uuid not null references public.participants on delete cascade, changed_after_context boolean not null default false, updated_at timestamptz not null default now(), unique(module_id,participant_id));
create table public.reactions (id uuid primary key default gen_random_uuid(), board_id uuid not null references public.boards on delete cascade, module_id text not null, participant_id uuid not null references public.participants on delete cascade, reaction text not null check (reaction in ('obsessed','safe','not you','wildcard')), unique(module_id,participant_id));
create table public.taste_insights (id uuid primary key default gen_random_uuid(), board_id uuid not null references public.boards on delete cascade, scope text not null, statement text not null check(length(statement)<=180), evidence_vote_ids uuid[] not null check(cardinality(evidence_vote_ids)>=2), confidence numeric not null check(confidence between 0 and 1), status text not null default 'pending' check(status in ('pending','accepted','corrected','dismissed')));
create table public.constraint_assessments (id uuid primary key default gen_random_uuid(), board_id uuid not null references public.boards on delete cascade, candidate_id text not null, score int not null check(score between 0 and 100), checks jsonb not null, unique(board_id,candidate_id));
create table public.activity_events (id uuid primary key default gen_random_uuid(), board_id uuid not null references public.boards on delete cascade, actor text not null check(actor in ('you','friend','agent')), body text not null check(length(body)<=240), created_at timestamptz not null default now());
alter table public.boards enable row level security; alter table public.participants enable row level security; alter table public.votes enable row level security; alter table public.reactions enable row level security; alter table public.taste_insights enable row level security; alter table public.constraint_assessments enable row level security; alter table public.activity_events enable row level security;
create policy "members read boards" on public.boards for select using (owner_id=auth.uid() or exists(select 1 from public.participants p where p.board_id=id and p.user_id=auth.uid() and (p.expires_at is null or p.expires_at>now())));
create policy "owners update boards" on public.boards for update using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "members read participants" on public.participants for select using(exists(select 1 from public.boards b where b.id=board_id and (b.owner_id=auth.uid() or exists(select 1 from public.participants me where me.board_id=b.id and me.user_id=auth.uid()))));
create policy "participants manage own votes" on public.votes for all using(participant_id in(select id from public.participants where user_id=auth.uid())) with check(participant_id in(select id from public.participants where user_id=auth.uid()));
create policy "participants manage own reactions" on public.reactions for all using(participant_id in(select id from public.participants where user_id=auth.uid())) with check(participant_id in(select id from public.participants where user_id=auth.uid()));
create policy "owners manage insights" on public.taste_insights for all using(board_id in(select id from public.boards where owner_id=auth.uid())) with check(board_id in(select id from public.boards where owner_id=auth.uid()));
create policy "owners manage assessments" on public.constraint_assessments for all using(board_id in(select id from public.boards where owner_id=auth.uid())) with check(board_id in(select id from public.boards where owner_id=auth.uid()));
create policy "members read activity" on public.activity_events for select using(board_id in(select id from public.boards where owner_id=auth.uid()) or board_id in(select board_id from public.participants where user_id=auth.uid()));
alter publication supabase_realtime add table public.votes, public.reactions, public.activity_events;
